// ============== CONFIGURATION ====================================
// --- UPDATE THESE VALUES WITH YOUR DETAILS ---

// 1. Google Drive Folder ID where the weekly sheets will be saved.
const FOLDER_ID = '1WY4Thfn7-PYs-W1Mp8enLgrskPQR-Saa';

// 2. MySQL Database Connection Details
const DB_HOST = 'db-distribution-accounting-do-user-2718740-0.h.db.ondigitalocean.com';
const DB_PORT = 25060;
const DB_NAME = 'das-db';
const DB_USER = 'thansoeaung';
const DB_PASSWORD = 'cW8w3EQxFFWZfKBZeWjNbQ==';

// 3. Your Full SQL Queries and Target Sheet (Tab) Names
const QUERIES_TO_RUN = [
  {
    sheetName: 'data',
    query: `
    WITH LatestPO AS (
    SELECT product_id, MAX(id) AS last_detail_id 
    FROM purchase_order_details GROUP BY product_id
),
BaseData AS (
    SELECT 
        p.*,
        NULLIF(TRIM(SUBSTRING_INDEX(p.description, ';', 1)), '') AS Ref_SKU_From_Product,
        COALESCE(NULLIF(TRIM(p.purchased_sku), ''), p.sku) AS Derived_Purchased_SKU
    FROM products AS p
    WHERE p.business_id = '84093770-29ad-4e8e-9da1-babe583c0d69'
      AND p.is_sellable = TRUE AND p.is_active = TRUE
),
SupplierSKULookup AS (
    SELECT 
        bd.id AS product_id,
        CASE 
            WHEN bd.is_purchasable = TRUE THEN 
                bd.Derived_Purchased_SKU
            ELSE 
                COALESCE(p_parent.purchased_sku, bd.sku)
        END AS Supplier_SKU
    FROM BaseData bd
    LEFT JOIN products AS p_parent ON p_parent.sku = bd.Derived_Purchased_SKU 
        AND p_parent.business_id = bd.business_id
),
SurveyAverages AS (
    SELECT 
        TRIM(SUBSTRING_INDEX(p_surveyed.description, ';', 1)) AS Ref_SKU_From_Note,
        ROUND(AVG(CASE WHEN sg.name = 'Retail' THEN (surv.unit_price / NULLIF(p_surveyed.weight, 0)) * p_ref.weight END), 2) AS Avg_Ref_Price_Retail_30D,
        ROUND(AVG(CASE WHEN sg.name = 'Street' THEN (surv.unit_price / NULLIF(p_surveyed.weight, 0)) * p_ref.weight END), 2) AS Avg_Ref_Price_Street_30D,
        ROUND(AVG(CASE WHEN sg.name = 'B2B' THEN (surv.unit_price / NULLIF(p_surveyed.weight, 0)) * p_ref.weight END), 2) AS Avg_Ref_Price_B2B_30D
    FROM price_surveys AS surv
    LEFT JOIN products AS p_surveyed ON p_surveyed.id = surv.product_id
    LEFT JOIN suppliers AS sup ON sup.id = surv.supplier_id
    LEFT JOIN supplier_groups AS sg ON sup.group_id = sg.id 
    LEFT JOIN products AS p_ref ON p_ref.sku = TRIM(SUBSTRING_INDEX(p_surveyed.description, ';', 1)) 
        AND p_ref.business_id = surv.business_id
    WHERE surv.business_id = '84093770-29ad-4e8e-9da1-babe583c0d69'
      AND surv.date >= DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY)
    GROUP BY 1
),
PriceCalculation AS (
    SELECT
        bd.sku, bd.name AS Product_Name, bd.weight AS Product_Weight, bd.length AS Product_Repacking_Cost, 
        bd.sales_price AS Catalogue_Price, bd.is_sellable AS Sellable, bd.is_purchasable AS Purchasable,
        sskul.Supplier_SKU, p_selling.sales_price AS Supplier_Price_Raw,
        (pod.detail_total_amount / NULLIF(pod.detail_qty, 0)) AS Direct_LastPOPrice,
        (pod_origin.detail_total_amount / NULLIF(pod_origin.detail_qty, 0)) AS Origin_LastPOPrice,
        plri_corp.unit_price AS Corp_Price_Num, plri_b2b.unit_price AS B2B_Price_Num,
        p_ref.weight AS Ref_SKU_Weight_Actual,
        sa.Avg_Ref_Price_Retail_30D, sa.Avg_Ref_Price_Street_30D, sa.Avg_Ref_Price_B2B_30D,
        COALESCE(pc2.name, pc1.name, pc.name) AS Category_L1,
        CASE WHEN pc2.name IS NOT NULL THEN pc1.name WHEN pc1.name IS NOT NULL THEN pc.name ELSE NULL END AS Category_L2,
        CASE WHEN pc2.name IS NOT NULL THEN pc.name ELSE NULL END AS Category_L3,
        CASE WHEN bd.is_purchasable = TRUE THEN bd.weight ELSE p_origin.weight END AS Purchased_SKU_Weight,
        bd.Derived_Purchased_SKU AS Purchased_SKU,
        bd.Ref_SKU_From_Product, p_ref.name AS Ref_SKU_Name_Actual
    FROM BaseData AS bd
    JOIN SupplierSKULookup sskul ON sskul.product_id = bd.id
    LEFT JOIN products AS p_selling ON p_selling.sku = sskul.Supplier_SKU AND p_selling.business_id = '7ef7c6c0-b59d-4be9-960c-7fa573038642'
    LEFT JOIN products AS p_origin ON p_origin.sku = bd.Derived_Purchased_SKU AND p_origin.business_id = bd.business_id
    LEFT JOIN LatestPO lp ON lp.product_id = bd.id
    LEFT JOIN purchase_order_details AS pod ON pod.id = lp.last_detail_id
    LEFT JOIN products AS p_ref ON p_ref.sku = bd.Ref_SKU_From_Product AND p_ref.business_id = bd.business_id
    LEFT JOIN SurveyAverages sa ON sa.Ref_SKU_From_Note = bd.Ref_SKU_From_Product
    LEFT JOIN LatestPO lp_origin ON lp_origin.product_id = p_origin.id
    LEFT JOIN purchase_order_details AS pod_origin ON pod_origin.id = lp_origin.last_detail_id
    LEFT JOIN product_categories AS pc ON bd.category_id = pc.id
    LEFT JOIN product_categories AS pc1 ON pc.parent_category_id = pc1.id
    LEFT JOIN product_categories AS pc2 ON pc1.parent_category_id = pc2.id
    LEFT JOIN price_lists pl_corp ON pl_corp.name = 'Corporate' AND pl_corp.business_id = bd.business_id
    LEFT JOIN price_list_rule_items plri_corp ON plri_corp.price_list_id = pl_corp.id AND plri_corp.product_id = bd.id
    LEFT JOIN price_lists pl_b2b ON pl_b2b.name = 'B2B' AND pl_b2b.business_id = bd.business_id
    LEFT JOIN price_list_rule_items plri_b2b ON plri_b2b.price_list_id = pl_b2b.id AND plri_b2b.product_id = bd.id
),
FinalCalculations AS (
    SELECT 
        pc.*,
        ROUND(Product_Weight / NULLIF(Purchased_SKU_Weight, 0), 4) AS Purchased_Conversion_Rate,
        ROUND(Supplier_Price_Raw * (Product_Weight / NULLIF(Purchased_SKU_Weight, 0)), 2) AS Calculated_Purchasing_Price,
        CASE 
            WHEN Purchasable = TRUE THEN Direct_LastPOPrice
            ELSE ROUND((Product_Weight / NULLIF(Purchased_SKU_Weight, 0)) * Origin_LastPOPrice, 2)
        END AS Calculated_Last_PO_Price,
        ROUND(Product_Weight * 300, 2) AS Delivery_Cost
    FROM PriceCalculation pc
)
SELECT
    SKU, Product_Name, Category_L1, Category_L2, Category_L3,
    Sellable, Purchasable,
    Purchased_SKU, Supplier_SKU,
    Product_Weight, Purchased_SKU_Weight, Purchased_Conversion_Rate,

    ROUND(Supplier_Price_Raw, 2) AS Supplier_Price,
    Calculated_Purchasing_Price AS Purchasing_Price,
    Calculated_Last_PO_Price AS Last_PO_Price,

    CASE 
        WHEN Calculated_Last_PO_Price IS NULL THEN 'No PO price known'
        WHEN Calculated_Purchasing_Price IS NULL THEN 'No purchasing price'
        WHEN Calculated_Purchasing_Price = '1' THEN 'No purchasing price'
        WHEN Calculated_Purchasing_Price > Calculated_Last_PO_Price THEN 'Purchasing price increased'
        WHEN LEAST(Catalogue_Price, Corp_Price_Num, B2B_Price_Num) < Total_Cost THEN 'Negative margin'
        WHEN Sellable = TRUE AND Catalogue_Price = '1' THEN 'Catalogue price not configured'
        ELSE 'No alert'
    END AS Price_Alert,

    Calculated_Purchasing_Price AS Final_Purchasing_Price,
    Product_Repacking_Cost, Delivery_Cost, Total_Cost,

    Catalogue_Price AS Cat_Price,
    ROUND((Catalogue_Price - Total_Cost) / NULLIF(Catalogue_Price, 0), 4) AS Cat_Margin_Percent,
    COALESCE(CAST(Corp_Price_Num AS CHAR), 'NA') AS Corp_Price,
    ROUND((Corp_Price_Num - Total_Cost) / NULLIF(Corp_Price_Num, 0), 4) AS Corp_Margin_Percent,
    COALESCE(CAST(B2B_Price_Num AS CHAR), 'NA') AS B2B_Price,
    ROUND((B2B_Price_Num - Total_Cost) / NULLIF(B2B_Price_Num, 0), 4) AS B2B_Margin_Percent,

    -- Final data for easy copy paste
    Category_L3 AS Category,
    SKU AS SKU_Copy,
    Product_Name AS Product,
    Catalogue_Price AS Catalogue,
    COALESCE(CAST(Corp_Price_Num AS CHAR), 'NA') AS Corporate,
    ROUND((Catalogue_Price - Corp_Price_Num) / NULLIF(Catalogue_Price, 0), 4) AS Corporate_discount,
    COALESCE(CAST(B2B_Price_Num AS CHAR), 'NA') AS B2B,
    ROUND((Catalogue_Price - B2B_Price_Num) / NULLIF(Catalogue_Price, 0), 4) AS B2B_discount

FROM (
    SELECT f.*, 
    ROUND(COALESCE(Calculated_Purchasing_Price, 0) + COALESCE(Product_Repacking_Cost, 0) + COALESCE(Delivery_Cost, 0), 2) AS Total_Cost
    FROM FinalCalculations f
) Final
ORDER BY Category_L3 ASC, Product_Name ASC, Product_Weight ASC;
    `
  }
];

// 4. Email Notification Configuration

const SPREADSHEET_ID = "17BxuaTjxvYqDytbMU7VRceNIqVYUqo0CD_e9LgUhz_o"; 
const TAB_ID = 0; // 0 is typically the very first tab in a sheet, so this is fine!
const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
var EMAIL_RECIPIENTS = "";

// Fixed: changed ss.getSheet() to ss.getSheets()
const email_sheet = ss.getSheets().find(s => s.getSheetId() === TAB_ID);

if (email_sheet) {
  EMAIL_RECIPIENTS = email_sheet.getRange("J2").getValue();
  Logger.log(EMAIL_RECIPIENTS);
} else {
  Logger.log("Error: Could not find a tab with ID " + TAB_ID);
}


// ============== END OF CONFIGURATION ===============================


/**
 * The main function to be scheduled weekly.
 */
function mainWeeklyDataPull() {
  try {
    // --- 1. Calculate Dates and Filename ---
    const today = new Date();
    // To get the date of the most recent Sunday for the filename.
    const lastSunday = new Date(today.setDate(today.getDate() - today.getDay()));
    const timezone = Session.getScriptTimeZone();
    const baseName = Utilities.formatDate(lastSunday, timezone, "'W'ww/yy 'M-Kitchen Product Pricelist'");

    // --- 2. Create the new Spreadsheet ---
    const parentFolder = DriveApp.getFolderById(FOLDER_ID);
    const newSheet = SpreadsheetApp.create(baseName);
    const tempFile = DriveApp.getFileById(newSheet.getId());
    parentFolder.addFile(tempFile);
    DriveApp.getRootFolder().removeFile(tempFile);

    Logger.log(`Successfully created new sheet: "${baseName}" (ID: ${newSheet.getId()})`);

    // --- 3. Establish Database Connection ---
    const dbUrl = "jdbc:mysql://" + DB_HOST + ":" + DB_PORT + "/" + DB_NAME;
    const conn = Jdbc.getConnection(dbUrl, DB_USER, DB_PASSWORD);
    Logger.log("Successfully connected to the database.");

    // --- 4. Loop Through Each Query and Populate Sheets ---
    QUERIES_TO_RUN.forEach(item => {
      Logger.log(`Fetching data for sheet: ${item.sheetName}`);

      const data = fetchData(conn, item.query);

      if (data && data.length > 1) { 
        Logger.log(`Retrieved ${data.length - 1} rows of data.`);
        writeDataToSheet(newSheet, item.sheetName, data);
      } else {
        Logger.log(`No data found for sheet: ${item.sheetName}.`);
        writeDataToSheet(newSheet, item.sheetName, [["No data found for the provided query"]]);
      }
    });

    // --- 5. Clean up Default Tabs ---
    const defaultSheet = newSheet.getSheetByName('Sheet1');
    if (defaultSheet) {
      newSheet.deleteSheet(defaultSheet);
    }
    conn.close();
    Logger.log("Process complete. Database connection closed.");

    // --- 6. Export Target Tab to CSV and Send Email ---
    Logger.log("Preparing email notification...");
    sendCsvEmail(newSheet, QUERIES_TO_RUN[0].sheetName, baseName);

  } catch (e) {
    Logger.log(`An error occurred: ${e.message} \nStack: ${e.stack}`);
  }
}

/**
 * Fetches data from the database using a given query.
 */
function fetchData(conn, query) {
  const stmt = conn.createStatement();
  const rs = stmt.executeQuery(query);
  const numCols = rs.getMetaData().getColumnCount();
  const headers = [];
  for (let col = 1; col <= numCols; col++) {
    headers.push(rs.getMetaData().getColumnLabel(col));
  }

  const data = [headers];

  while (rs.next()) {
    const row = [];
    for (let col = 1; col <= numCols; col++) {
      row.push(rs.getString(col));
    }
    data.push(row);
  }

  rs.close();
  stmt.close();
  return data;
}

/**
 * Writes a 2D array of data to a specified sheet.
 */
function writeDataToSheet(ss, sheetName, data) {
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
  }
  sheet.clear();

  if (data && data.length > 0) {
    const range = sheet.getRange(1, 1, data.length, data[0].length);
    range.setValues(data);
    sheet.setFrozenRows(1);
    Logger.log(`Wrote data to sheet: "${sheetName}"`);
  }
}

/**
 * Converts a specific sheet tab to a CSV blob and emails it to the team.
 * @param {Spreadsheet} ss The spreadsheet object.
 * @param {string} targetSheetName The specific tab name to convert.
 * @param {string} baseName The base filename used for subject and attachment.
 */
function sendCsvEmail(ss, targetSheetName, baseName) {
  const targetSheet = ss.getSheetByName(targetSheetName);
  if (!targetSheet) {
    Logger.log(`Error: Could not find tab "${targetSheetName}" to export to CSV.`);
    return;
  }

  // Get data from the sheet and convert to a CSV string format
  const data = targetSheet.getDataRange().getValues();
  let csvString = "";

  for (let i = 0; i < data.length; i++) {
    const row = data[i].map(cell => {
      // Escape inner quotes and wrap cells containing commas/newlines in quotes
      let cellStr = cell.toString();
      if (cellStr.includes(",") || cellStr.includes("\n") || cellStr.includes('"')) {
        cellStr = '"' + cellStr.replace(/"/g, '""') + '"';
      }
      return cellStr;
    });
    csvString += row.join(",") + "\r\n";
  }

  // Convert string to an email attachment blob
  const attachmentFilename = `${baseName}.csv`;
  const csvBlob = Utilities.newBlob(csvString, 'text/csv', attachmentFilename);

  // Draft and send email
  const subject = `Weekly Data Update: ${baseName}`;
  const body = `Hello Team,\n\nPlease find attached the weekly automated CSV data snapshot for: ${baseName}.\n\nThis is an automated system email.`;

  MailApp.sendEmail({
    to: EMAIL_RECIPIENTS,
    subject: subject,
    body: body,
    attachments: [csvBlob]
  });

  Logger.log(`Notification email successfully sent to: ${EMAIL_RECIPIENTS}`);
}

/**
 * ONE-TIME SETUP: Run this function manually ONCE to create the weekly trigger.
 */
function createWeeklyTrigger() {
  const allTriggers = ScriptApp.getProjectTriggers();
  for (const trigger of allTriggers) {
    if (trigger.getHandlerFunction() === 'mainWeeklyDataPull') {
      ScriptApp.deleteTrigger(trigger);
    }
  }

  ScriptApp.newTrigger('mainWeeklyDataPull')
    .timeBased()
    .onWeekDay(ScriptApp.WeekDay.MONDAY)
    .atHour(4) // Triggers between 4:00 AM and 5:00 AM every Monday
    .create();

  Logger.log('Successfully created the weekly trigger for Monday mornings.');
}
